# Surah At-Tawbah (chapter 9) — part 10: ayat 85-94 (IDs 1320-1329)
SURAH = 9

ENTRIES = {
1320: (
"اور — ان — کے مال اور ان کی اولاد — تجھے — تعجب میں نہ ڈالیں — بے شک — اللہ — چاہتا ہے — انہیں — اس — سے عذاب دے دنیا کی زندگی میں — اور — ان کے جان — ختم ہو جائیں — وہ — کافر — ہوں",
"""۱۔ منافقوں کے مال — عارضی — اور آفتیں۔
۲۔ ’’وَلَا تُعْجِبْكَ أَمْوَالُهُمْ وَأَوْلَادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ أَن يُعَذِّبَهُم بِهَا فِي الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ‘‘ — اور — ان — کے مال اور ان کی اولاد — تجھے — تعجب میں نہ ڈالیں — بے شک — اللہ — چاہتا ہے — انہیں — اس — سے عذاب دے دنیا کی زندگی میں — اور — ان کے جان — ختم ہو جائیں — وہ — کافر — ہوں — یعنی منافقوں کی دولت — دنیا میں بھی — عذاب کا سبب ہے۔
۳۔ عملی سبق: دنیوی دولت — نہ — کامیابی کی علامت ہے۔"""
),
1321: (
"اور — جب — کوئی سورہ — اتاری جاتی ہے — کہ — اللہ پر ایمان لاؤ — اور — اس کے رسولؐ کے ساتھ جہاد کرو — تو — ان — میں — آسانی والے — آپؐ سے — اجازت مانگتے ہیں — اور — کہتے ہیں — ہمیں — بیٹھنے والوں کے ساتھ — چھوڑ دو",
"""۱۔ نفاق — آسانی کی — دلیل بھی بناتا ہے۔
۲۔ ’’وَإِذَا أُنزِلَتْ سُورَۃٌ أَنْ آمِنُوا بِاللَّهِ وَجَاهِدُوا مَعَ رَسُولِهِ اسْتَأْذَنَكَ أُولُو الطَّوْلِ مِنْهُمْ وَقَالُوا ذَرْنَا نَكُن مَّعَ الْقَاعِدِينَ‘‘ — اور — جب — کوئی سورہ — اتاری جاتی ہے — کہ — اللہ پر ایمان لاؤ — اور — اس کے رسولؐ کے ساتھ جہاد کرو — تو — ان — میں — آسانی والے — آپؐ سے — اجازت مانگتے ہیں — اور — کہتے ہیں — ہمیں — بیٹھنے والوں کے ساتھ — چھوڑ دو — یعنی منافق — قرآن کی سورہ — کی بھی اجازت مانگنے کی بنیاد — بناتے ہیں۔
۳۔ عملی سبق: دل کی بیماری — کسی — بھی — چیز سے — انحراف کی وجہ بنتی ہے۔"""
),
1322: (
"وہ — اس لیے راضی ہو گئے — کہ — وہ — پیچھے رہ جانے والوں کے ساتھ ہوں — اور — ان کے دلوں پر — مہر — لگا دی گئی — پس — وہ — نہیں سمجھتے",
"""۱۔ منافق — بیٹھے رہنے پر — راضی — اور — مہر شدہ دلوں والے۔
۲۔ ’’رَضُوا بِأَن يَكُونُوا مَعَ الْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ‘‘ — وہ — اس لیے راضی ہو گئے — کہ — وہ — پیچھے رہ جانے والوں کے ساتھ ہوں — اور — ان کے دلوں پر — مہر — لگا دی گئی — پس — وہ — نہیں سمجھتے — یعنی منافق — خود کو — پیچھے رہ جانے والوں میں شامل — سمجھتے ہیں اور — ان کے دل — مہر شدہ — ہیں۔
۳۔ عملی سبق: نفاق — دل کو — سمجھنے سے — محروم — کر دیتا ہے۔"""
),
1323: (
"لیکن — رسولؐ — اور — جو لوگ — اس کے ساتھ ایمان لائے — انہوں نے — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اور — یہی لوگ — تمام بھلائیوں — کے لیے ہیں — اور یہی لوگ — کامیاب ہیں",
"""۱۔ رسولؐ اور مؤمنین — حقیقی طور پر — جہاد کرنے والے۔
۲۔ ’’لَّٰكِنِ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ جَاهَدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ وَأُولَٰئِكَ لَهُمُ الْخَيْرَاتُ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ‘‘ — لیکن — رسولؐ — اور — جو لوگ — اس کے ساتھ ایمان لائے — انہوں نے — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اور — یہی لوگ — تمام بھلائیوں — کے لیے ہیں — اور یہی لوگ — کامیاب ہیں — یعنی رسولؐ اور مومن — حقیقی جہاد کرنے والے ہیں — ان کے لیے — سب بھلائیاں — ہیں۔
۳۔ عملی سبق: رسولؐ کی پیروی — کامیابی کی ضمانت ہے۔"""
),
1324: (
"اللہ — نے — ان کے لیے — ایسی جنتوں — کو — تیار کر رکھا ہے — جن کے نیچے — نہریں بہہتی ہیں — وہ — ان میں — ہمیشہ رہیں گے — یہی — عظیم کامیابی — ہے",
"""۱۔ مؤمنوں کے لیے — اللہ کی خوش خبری — دوبارہ۔
۲۔ ’’أَعَدَّ اللَّهُ لَهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ذَٰلِكَ الْفَوْزُ الْعَظِيمُ‘‘ — اللہ — نے — ان کے لیے — ایسی جنتوں — کو — تیار کر رکھا ہے — جن کے نیچے — نہریں بہہتی ہیں — وہ — ان میں — ہمیشہ رہیں گے — یہی — عظیم کامیابی — ہے — یعنی مؤمنوں کے لیے — اللہ — نے جنتیں تیار کی ہیں؛ یہ — عظیم کامیابی ہے۔
۳۔ عملی سبق: جنت — ہمیشہ — آپ کا انتظار کر رہی ہے۔"""
),
1325: (
"اور — اعرابی — عذر والے — آئے — کہ — انہیں اجازت دی جائے — اور — وہ لوگ — بیٹھے رہے — جنہوں نے — اللہ اور اس کے رسولؐ — سے — جھوٹ — بولا — ان — کافروں میں — سے — جو — کفر کرتے ہیں — انہیں — دردناک عذاب — پہنچے گا",
"""۱۔ اعرابی — عذر والے — اور جھوٹ بولنے والے۔
۲۔ ’’وَجَاءَ الْمُعَذِّرُونَ مِنَ الْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ الَّذِينَ كَذَبُوا اللَّهَ وَرَسُولَهُ سَيُصِيبُ الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابٌ أَلِيمٌ‘‘ — اور — اعرابی — عذر والے — آئے — کہ — انہیں اجازت دی جائے — اور — وہ لوگ — بیٹھے رہے — جنہوں نے — اللہ اور اس کے رسولؐ — سے — جھوٹ — بولا — ان — کافروں میں — سے — جو — کفر کرتے ہیں — انہیں — دردناک عذاب — پہنچے گا — یعنی کچھ اعرابی — سچے عذر والے تھے — اور کچھ — جھوٹے؛ جھوٹوں کے لیے — دردناک عذاب۔
۳۔ عملی سبق: سچ — تو — ہمیشہ ہے — مگر — جھوٹ — قابلِ عذاب ہے۔"""
),
1326: (
"کمزوروں — مریضوں — اور ان — پر جنہیں — خرچ کرنے کے لیے — کچھ نہیں ملا — کوئی حرج نہیں — اگر وہ — اللہ اور اس کے رسولؐ — کے لیے — خیر — چاہیں — نیکوکاروں پر — کوئی — راہ — نہیں — اور — اللہ — بخشنے والا مہربان ہے",
"""۱۔ کمزور، مریض اور فقراء — جہاد سے — بری ہیں۔
۲۔ ’’لَّيْسَ عَلَى الضُّعَفَاءِ وَلَا عَلَى الْمَرْضَىٰ وَلَا عَلَى الَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا لِلَّهِ وَرَسُولِهِ مَا عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — کمزوروں — مریضوں — اور ان — پر جنہیں — خرچ کرنے کے لیے — کچھ نہیں ملا — کوئی حرج نہیں — اگر وہ — اللہ اور اس کے رسولؐ — کے لیے — خیر — چاہیں — نیکوکاروں پر — کوئی — راہ — نہیں — اور — اللہ — بخشنے والا مہربان ہے — یعنی کمزور، مریض اور فقراء — اگر رسولؐ کے لیے خیر چاہیں — تو ان پر — کوئی الزام — نہیں۔
۳۔ عملی سبق: نیت — سچی ہو تو — کمزور کا عذر — قبول ہے۔"""
),
1327: (
"اور — نہ — ان — لوگوں پر — جب — وہ — آپؐ کے پاس آئے — تاکہ — آپؐ انہیں — سواری — دیں — آپؐ نے کہا — میں آپ کو — سوار نہیں کر سکتا — وہ — روتے ہوئے — واپس لوٹ گئے — اس لیے کہ — انہیں خرچ کرنے کے لیے کچھ — نہیں ملا",
"""۱۔ تبوک — غریبوں کی — درد کی تصویر۔
۲۔ ’’وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوْا وَأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَنًا أَلَّا يَجِدُوا مَا يُنفِقُونَ‘‘ — اور — نہ — ان — لوگوں پر — جب — وہ — آپؐ کے پاس آئے — تاکہ — آپؐ انہیں — سواری — دیں — آپؐ نے کہا — میں آپ کو — سوار نہیں کر سکتا — وہ — روتے ہوئے — واپس لوٹ گئے — اس لیے کہ — انہیں خرچ کرنے کے لیے کچھ — نہیں ملا — یعنی تبوک میں — کچھ غریب — روتے ہوئے — جہاد — میں شامل نہیں ہو سکے — رسولؐ انہیں سوار نہیں کر سکے۔
۳۔ عملی سبق: امداد — اگر دستیاب ہو — ضرور — مہیا کرو۔"""
),
1328: (
"صرف — ان لوگوں پر — راہ ہے — جو آپؐ سے — اجازت مانگتے ہیں — حالانکہ وہ — امیر ہیں — وہ — پیچھے رہ جانے والوں کے ساتھ ہونے پر — راضی ہوئے — اور — اللہ نے — ان کے دلوں پر — مہر لگا دی — پس — وہ — نہیں جانتے",
"""۱۔ امیروں کی — جہاد سے — گریز — سب سے بڑا جرم۔
۲۔ ’’إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَسْتَأْذِنُونَكَ وَهُمْ أَغْنِيَاءُ رَضُوا بِأَن يَكُونُوا مَعَ الْخَوَالِفِ وَطَبَعَ اللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ‘‘ — صرف — ان لوگوں پر — راہ ہے — جو آپؐ سے — اجازت مانگتے ہیں — حالانکہ وہ — امیر ہیں — وہ — پیچھے رہ جانے والوں کے ساتھ ہونے پر — راضی ہوئے — اور — اللہ نے — ان کے دلوں پر — مہر لگا دی — پس — وہ — نہیں جانتے — یعنی امیر لوگ — جہاد سے — بچنے کے لیے — جھوٹ عذر پیش کرتے ہیں؛ ان کے دل — مہر شدہ — ہیں۔
۳۔ عملی سبق: امیر — اگر جہاد سے بچے — تو — سب سے بڑا نفاق — ہے۔"""
),
1329: (
"وہ — آپ کو — عذر پیش کریں گے جب — آپ — ان کے پاس — واپس لوٹیں گے — کہدو — عذر پیش نہ کرو — ہم — تمہاری بات پر — ایمان نہ لائیں گے — اللہ — نے — ہمیں — تمہارے حالات — کی خبر دے دی — اور — اللہ — اور اس کا رسولؐ — عنقریب — تمہارے اعمال — دیکھ لیں گے — پھر — تم — غیب و شہادت — کے جاننے والے — کی طرف — لوٹائے جاؤ گے — پس — وہ — تمہیں — تمہارا عمل — بتا دے گا",
"""۱۔ جہاد سے بچنے والے — واپس لوٹنے پر — جھوٹے عذر پیش کریں گے۔
۲۔ ’’يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا اللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ ثُمَّ تُرَدُّونَ إِلَىٰ عَالِمِ الْغَيْبِ وَالشَّهَادَۃِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — وہ — آپ کو — عذر پیش کریں گے جب — آپ — ان کے پاس — واپس لوٹیں گے — کہدو — عذر پیش نہ کرو — ہم — تمہاری بات پر — ایمان نہ لائیں گے — اللہ — نے — ہمیں — تمہارے حالات — کی خبر دے دی — اور — اللہ — اور اس کا رسولؐ — عنقریب — تمہارے اعمال — دیکھ لیں گے — پھر — تم — غیب و شہادت — کے جاننے والے — کی طرف — لوٹائے جاؤ گے — پس — وہ — تمہیں — تمہارا عمل — بتا دے گا — یعنی منافق — واپس لوٹنے پر — جھوٹے عذر پیش کریں گے؛ مگر — اللہ — اور رسولؐ — سب جانتے ہیں۔
۳۔ عملی سبق: اللہ — ہر چیز کا علم رکھتا ہے؛ جھوٹ کی بنیاد — کسی کام نہیں آئے گی۔"""
),
}
